mapper.select:
SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM send_real_recipient_whitelist
WHERE customer_id = #{customerId}
  AND channel_id = #{channelId}
  AND is_active = 1
  AND NVL(is_deleted, 0) = 0

mapper.insert:
INSERT INTO send_real_recipient_whitelist ( customer_id, channel_id, description, is_active,
) VALUES ( #{customerId, jdbcType=BIGINT}, #{channelId, jdbcType=BIGINT}, #{description, jdbcType=VARCHAR}, 10,
)
